int full_is_equal(uint64_t x[MATMUL_M][OUT_COLS], const uint64_t y[MATMUL_M][OUT_COLS]) {
  for (int i = 0; i < MATMUL_M; i++)
    for (int j = 0; j < OUT_COLS; j++)
      if (x[i][j] != y[i][j]) return 0;
  return 1;
}

